with valid as (select *, lower(merchant) as merchant_lower, coalesce(merchant, 'NONE') as resolved_merchant from transactions where txn_time > timestamp '2023-12-26 19:00:00') select date_trunc('quarter', txn_time) as quarter_start, (unix_timestamp(max(txn_time)) - unix_timestamp(min(txn_time))) / 60 as span_minutes, min(txn_time) as first_txn_time, min(amount) as min_amount, count(*) as row_count from valid group by date_trunc('quarter', txn_time) order by span_minutes desc nulls first
